package com.learnagent.digest;
import jakarta.persistence.*;import java.time.*;import java.util.UUID;
@Entity@Table(name="external_resources")public class ExternalResource{@Id private UUID id;@Column(name="digest_id")private UUID digestId;@Column(name="course_id")private UUID courseId;@Column(nullable=false)private String title;@Column(nullable=false,length=2000)private String url;@Column(name="source_name")private String sourceName;@Column(nullable=false,columnDefinition="text")private String summary;@Column(name="published_at")private Instant publishedAt;@Column(name="discovered_at",nullable=false)private Instant discoveredAt;@Column(name="local_markdown_path")private String localMarkdownPath;protected ExternalResource(){}public ExternalResource(UUID digest,UUID course,String title,String url,String source,String summary,Instant published,String path){id=UUID.randomUUID();digestId=digest;courseId=course;this.title=title;this.url=url;sourceName=source;this.summary=summary;publishedAt=published;localMarkdownPath=path;discoveredAt=Instant.now();}public UUID getId(){return id;}public UUID getDigestId(){return digestId;}public UUID getCourseId(){return courseId;}public String getTitle(){return title;}public String getUrl(){return url;}public String getSourceName(){return sourceName;}public String getSummary(){return summary;}public Instant getPublishedAt(){return publishedAt;}public Instant getDiscoveredAt(){return discoveredAt;}public String getLocalMarkdownPath(){return localMarkdownPath;}}
